import React from 'react';

function Games(){
    return(
        <div className='game_page'>
            <div className='game-vidContainer'>
                <video autoPlay loop muted>
                    <source  src = {require("./images/sleepingBearPurpFlower.mp4")}></source>
                </video>
                <h1 id='gameVidTitle'>The Great Escape</h1>
                <div className='gameVid_block'>
                    
                    <p id='gameVidText'>
                        The Great Escape follows a young princess Matilda as she attempts to revitalize the disheveled Kingdom she once called home. 
                        She must navigate the dangerous land of Vincentra fending off the deadly foes and tackling the corrupt cabinet appointed at her fathers rule. 
                        Making use of the gear and friends she finds along the way, Matilda must bring back the Kingdom of Vincentra to its previous glory and rid the land of the evil that envelops it.
                        <br/><br/>
                        Check out the current status of The Great Escape below.
                    </p>
                </div>
            </div>
            <h1 id = "game_prevTitle">Game Preview</h1>
            <div className='game_prevVid'>
                <video controls>
                    <source  src = {require("./images/theGreatEscapePrevVideo.mp4")}></source>
                </video>
            </div>
            <p id='game_prevText'>
                The Great Escape is currently in the early stages of development, but work continues to push a finished product to the Apple App Store in the coming year. 
                This website will reflect the new changes as updates are developed.
            </p>
        </div>
    )
}

export default Games;