import React from 'react';

function Story(){
    return(
        <div className='story_page'>
            <h1 className='story_title'>From the Beginning</h1>
            <div className='story_topTextCont'>
                <h1 id='story_topText'>
                    Love to create not to be recognized, but to recognize the love to create 
                </h1>
                <img id = "storyImg_johnPark" src = {require("./images/johnsonParkDiscGolf.jpg")} alt = "Grand Rapids Johnson Park"></img>
            </div>
            <p id='story_disc1'>
                Run Wild was founded on the priciple that anyone can succeed if you love what you do. If you wake each morning inspired to be great one day that just might be true.
            </p>
            <div className='story_VidContainer'>
                <video loop autoPlay muted>
                    <source src = {require("./images/M-22Farmland.mp4")}></source>
                </video>
            </div>
            <div className='story_bottomCont'>
                <h1 id='story_bottomText'>
                    Inspire a generation of dreamers
                </h1>
                <img id = "storyImg_sleepingBear" src = {require("./images/sleepingBearLakeShore.jpg")} alt = "Sleeping Bear Dunes National Lakeshore"></img>
            </div>
            <p id='story_disc2'>
                Run Wild is more that a name, but a montra for those who are lost to follow what makes their heart sing. Run as fast as you can, as long as you can, in the direction you know you can.
            </p>
        </div>
    )
}

export default Story;