import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import {FaTimes, FaBars} from 'react-icons/fa';

function Navbar(){

    const [menuOpen, setMenuOpen] = useState(false);
    
    return(
        <nav className='nav'>

            <Link id = "nav_title" to ="/"><img id = "logo" src = {require("./images/Run_Wild_Logo_Grnback.png")} alt="Run Wild Logo"></img></Link>
            <ul className ={menuOpen ? "open" : ""}>
                <li>
                    <Link className = "navLink" to = "/story">Our Story</Link>
                </li>
                <li>
                    <Link className = "navLink" to = "/games">Games</Link>
                </li>
                <li>
                    <Link className = "navLink" to = "/films">Films</Link>
                </li>
                <li>
                    <Link className = "navLink" to = "/contact">Contact</Link>
                </li>
            </ul>
            <button className={menuOpen ? 'nav_btn nav_hiddenBtn' : 'nav_btn nav_openBtn'} onClick={() => { setMenuOpen(!menuOpen)} }>
                <FaBars/>
            </button>
            <button className={menuOpen ? 'nav_btn nav_activeBtn' : 'nav_btn nav_closeBtn'} onClick={() => { setMenuOpen(!menuOpen)}}>
                <FaTimes/>
            </button>
        </nav>
    )
}

export default Navbar;